effect.shader:

    vec4 newLayer( vec4 a, vec4 b) {
    return a * (1. - b.a) + b;
    }

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

   /////////////////////////

   float random(float x) {

        return fract(sin(x) * 10000.);

    }

    float noise(vec2 p) {

     	return random(p.x + p.y * 10000.);

    }

    vec2 sw(vec2 p) { return vec2(floor(p.x), floor(p.y)); }
    vec2 se(vec2 p) { return vec2(ceil(p.x), floor(p.y)); }
    vec2 nw(vec2 p) { return vec2(floor(p.x), ceil(p.y)); }
    vec2 ne(vec2 p) { return vec2(ceil(p.x), ceil(p.y)); }

    float smoothNoise(vec2 p) {

        vec2 interp = smoothstep(0., 1., fract(p));
        float s = mix(noise(sw(p)), noise(se(p)), interp.x);
        float n = mix(noise(nw(p)), noise(ne(p)), interp.x);
        return mix(s, n, interp.y);

    }

    float fractalNoise(vec2 p) {

        float n = 0.;
        n += smoothNoise(p);
        n += smoothNoise(p * 2.) / 2.;
        n += smoothNoise(p * 4.) / 4.;
        n += smoothNoise(p * 8.) / 8.;
        n += smoothNoise(p * 16.) / 16.;
        n /= 1. + 1./2. + 1./4. + 1./8. + 1./16.;
        return n;

    }

    void main ()
    {

        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 blackTex = texture2DCv(black.texture,acScreenNorm);

        vec2 TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
        TanRyu.y*=acLayerSize.y/acLayerSize.x;

        TanRyu /= 1.0;
        TanRyu *= rot2m(angle*0.0174533);
        // TanRyu += position*vec2(-1.,1.)/500.;
        TanRyu += vec2((0.0+position.x), (-350.0+position.y))*vec2(-1.,1.)/500.;

        /////////////////////////


    	vec4 result;

    	// vec2 uv = fragCoord.xy / iResolution.xy;
    	vec2 uv = TanRyu;
        vec2 nuv = vec2(uv.x - 1.0 / 6., uv.y);
        uv *= vec2(1., -1.);

    	float x = fractalNoise(nuv * progressd);
    	// vec4 coloring = vec4(color.rgb,1.0) * texColor.a;
        vec3 final = mix(vec3(x), texture2DCv(black.texture, uv).xyz, pow(abs(uv.y), 4.0));

        result = vec4(final, 1.) * vec4(color.rgb,1.0);

   	vec4 factorr = (result + (result*thick)) * alpha;

            vec4 targetLuma = factorr;
            const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
            float luma = dot(targetLuma.rgb, luminanceWeighting);
            float lowThresholdB = (lowThreshold*(1.0+1.0))-0.001;
            float lowThresholdA = lowThresholdB-max(1.0, 0.00001);
            float highThresholdA = (1.0*(1.0+1.0)-1.0)+0.001;
            float highThresholdB = highThresholdA+max(1.0, 0.00001);
            float lowBlend = smoothstep( lowThresholdA, lowThresholdB, luma );
            float highBlend = 1. - smoothstep( highThresholdA, highThresholdB, luma );
            float lumafx = min(lowBlend,highBlend);
            vec4 factor = targetLuma*lumafx;

        vec4 resultfinal;
        if( blendMode==0 ) {                // normal
            factor *= texColor.a;
            resultfinal = newLayer(texColor, factor) * texColor.a;
        } else if( blendMode==1 ) {         // multiply
            vec4 c = factor + vec4(1.)*(1.-factor.a);
            resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( blendMode==2 ) {         // screen
            resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }

    	gl_FragColor = mix(texColor,resultfinal,1.0) * texColor.a;
    }
